begin;
select plan(25);
select has_column('public', 'generation_jobs', 'recoveries', 'recovery column exists and is non-null');
select col_default_is('public', 'generation_jobs', 'recoveries', '0', 'recoveries defaults to zero');
select col_not_null('public', 'generation_jobs', 'recoveries', 'recovery column exists and is non-null');
insert into auth.users (id, email) values ('08000000-0000-4000-8000-000000000001', 'jobs-db@example.test');
insert into public.generation_jobs (id,user_id,operation,idempotency_key,heartbeat_at) values
('08000000-0000-4000-8000-000000000002','08000000-0000-4000-8000-000000000001','generate','test',now()-interval '1 hour');
select lives_ok($$select app.save_job_step('08000000-0000-4000-8000-000000000002','first','false')$$);
select is((select steps from public.generation_jobs where id='08000000-0000-4000-8000-000000000002'), '{"done":{"first":false}}'::jsonb);
select ok((select heartbeat_at = now() from public.generation_jobs where id='08000000-0000-4000-8000-000000000002'));
select lives_ok($$select app.save_job_step('08000000-0000-4000-8000-000000000002','second','null')$$);
select is((select steps from public.generation_jobs where id='08000000-0000-4000-8000-000000000002'), '{"done":{"first":false,"second":null}}'::jsonb);
select lives_ok($$select app.touch_job('08000000-0000-4000-8000-000000000002','polling')$$);
select is((select stage_detail from public.generation_jobs where id='08000000-0000-4000-8000-000000000002'),'polling');
update public.generation_jobs set heartbeat_at = now()-interval '1 hour' where id='08000000-0000-4000-8000-000000000002';
select is(app.record_job_recovery('08000000-0000-4000-8000-000000000002'),1);
select is(app.record_job_recovery('08000000-0000-4000-8000-000000000002'),null::integer,'fresh/concurrently claimed job is not recovered twice');
select throws_ok($$select app.save_job_step('08000000-0000-4000-8000-000000000002','bad.path','1')$$,'22023','invalid step');
select ok(not has_function_privilege('authenticated','app.save_job_step(uuid,text,jsonb)','execute'));
select ok(not has_function_privilege('anon','app.touch_job(uuid,text)','execute'));
select ok(has_function_privilege('service_role','app.record_job_recovery(uuid)','execute'));
select ok(not has_function_privilege('anon','app.save_job_step(uuid,text,jsonb)','execute'), 'anon cannot execute save_job_step(uuid,text,jsonb)');
select ok(not has_function_privilege('authenticated','app.save_job_step(uuid,text,jsonb)','execute'), 'authenticated cannot execute save_job_step(uuid,text,jsonb)');
select ok((select prosecdef and proconfig @> array['search_path=app, public, pg_temp'] from pg_proc where oid='app.save_job_step(uuid,text,jsonb)'::regprocedure), 'definer and fixed search path for save_job_step(uuid,text,jsonb)');
select ok(not has_function_privilege('anon','app.touch_job(uuid,text)','execute'), 'anon cannot execute touch_job(uuid,text)');
select ok(not has_function_privilege('authenticated','app.touch_job(uuid,text)','execute'), 'authenticated cannot execute touch_job(uuid,text)');
select ok((select prosecdef and proconfig @> array['search_path=app, public, pg_temp'] from pg_proc where oid='app.touch_job(uuid,text)'::regprocedure), 'definer and fixed search path for touch_job(uuid,text)');
select ok(not has_function_privilege('anon','app.record_job_recovery(uuid)','execute'), 'anon cannot execute record_job_recovery(uuid)');
select ok(not has_function_privilege('authenticated','app.record_job_recovery(uuid)','execute'), 'authenticated cannot execute record_job_recovery(uuid)');
select ok((select prosecdef and proconfig @> array['search_path=app, public, pg_temp'] from pg_proc where oid='app.record_job_recovery(uuid)'::regprocedure), 'definer and fixed search path for record_job_recovery(uuid)');
select * from finish();
rollback;
